package cn.local.rainreminder;
import android.app.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.os.Build;import android.view.*;import android.widget.*;
final class Ui {
 static Typeface regular,bold;
 static Typeface font(android.content.Context c){if(regular==null){regular=c.getResources().getFont(R.font.ui);bold=Typeface.create(regular,Typeface.BOLD);}return regular;}
 static Typeface strong(android.content.Context c){font(c);return bold;}
 static final int PAGE=Color.rgb(247,248,250);
 static final int GREEN=Color.rgb(33,92,82),INK=Color.rgb(29,43,40),MUTED=Color.rgb(92,109,102);
 static int dp(Activity a,int n){return (int)(a.getResources().getDisplayMetrics().density*n);}
 static GradientDrawable bg(Activity a,int c){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(a,14));return d;}
 static TextView text(Activity a,String s,int size){TextView t=new TextView(a);t.setIncludeFontPadding(false);t.setText(s);t.setTextSize(size);t.setTextColor(INK);t.setTypeface(size>=20?strong(a):font(a));t.setLineSpacing(dp(a,2),1);t.setPadding(0,dp(a,4),0,dp(a,4));return t;}
 static TextView hint(Activity a,String s){TextView t=text(a,s,13);t.setTextColor(MUTED);return t;}
 static LinearLayout column(Activity a){LinearLayout l=new LinearLayout(a);l.setOrientation(1);return l;}
 static LinearLayout screen(Activity a,String title){return screen(a,title,true);}
 static LinearLayout screen(Activity a,String title,boolean back){LinearLayout page=column(a);page.setBackgroundColor(PAGE);page.setOnApplyWindowInsetsListener((v,i)->{int top,bottom;if(Build.VERSION.SDK_INT>=30){android.graphics.Insets b=i.getInsets(WindowInsets.Type.systemBars());top=b.top;bottom=b.bottom;}else{top=i.getSystemWindowInsetTop();bottom=i.getSystemWindowInsetBottom();}page.setPadding(0,top,0,bottom);return i;});LinearLayout bar=new LinearLayout(a);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(a,12),dp(a,6),dp(a,20),dp(a,6));if(back){Button b=link(a,bar,"‹",a::finish);b.setTextSize(28);b.setContentDescription("返回");b.setLayoutParams(new LinearLayout.LayoutParams(dp(a,44),dp(a,44)));}TextView heading=text(a,title,21);bar.addView(heading,new LinearLayout.LayoutParams(0,-2,1));page.addView(bar,new LinearLayout.LayoutParams(-1,dp(a,56)));ScrollView sc=new ScrollView(a);sc.setFillViewport(true);sc.setClipToPadding(false);LinearLayout l=column(a);int width=(int)(a.getResources().getDisplayMetrics().widthPixels/a.getResources().getDisplayMetrics().density);int side=Math.max(20,(width-640)/2);l.setPadding(dp(a,side),dp(a,8),dp(a,side),dp(a,28));sc.addView(l);page.addView(sc,new LinearLayout.LayoutParams(-1,0,1));a.setContentView(page);page.requestApplyInsets();a.getWindow().setStatusBarColor(PAGE);a.getWindow().setNavigationBarColor(PAGE);a.getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);return l;}
 static LinearLayout card(Activity a,LinearLayout p){LinearLayout l=column(a);l.setPadding(dp(a,16),dp(a,14),dp(a,16),dp(a,14));l.setBackground(bg(a,Color.WHITE));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(a,12),0,0);p.addView(l,lp);return l;}
 static Button button(Activity a,LinearLayout p,String s,Runnable action){Button b=new Button(a);b.setIncludeFontPadding(false);b.setText(s);b.setTextSize(15);b.setTypeface(strong(a));b.setTextColor(GREEN);b.setAllCaps(false);b.setStateListAnimator(null);b.setElevation(0);b.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x24335C50),bg(a,Color.rgb(233,240,235)),null));b.setPadding(dp(a,12),dp(a,8),dp(a,12),dp(a,8));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(a,8),0,0);b.setMinHeight(dp(a,48));p.addView(b,lp);b.setOnClickListener(v->action.run());return b;}
 static Button primary(Activity a,LinearLayout p,String s,Runnable action){Button b=button(a,p,s,action);b.setTextColor(Color.WHITE);b.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x30FFFFFF),bg(a,GREEN),null));return b;}
 static Button link(Activity a,LinearLayout p,String s,Runnable action){Button b=button(a,p,s,action);b.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x18335C50),null,bg(a,Color.WHITE)));b.setMinHeight(dp(a,40));b.setMinimumWidth(0);b.setMinWidth(0);b.setPadding(dp(a,6),0,dp(a,6),0);return b;}
 static LinearLayout fold(Activity a,LinearLayout p,String label){LinearLayout inside=column(a);Button b=link(a,p,label+"  ›",()->{});inside.setVisibility(View.GONE);b.setOnClickListener(v->{boolean open=inside.getVisibility()!=View.VISIBLE;inside.setVisibility(open?View.VISIBLE:View.GONE);b.setText(label+(open?"  ⌄":"  ›"));});p.addView(inside);return inside;}
 static EditText field(Activity a,LinearLayout p,String label,String value,int input){p.addView(hint(a,label));EditText e=new EditText(a);e.setIncludeFontPadding(false);e.setSingleLine();e.setTextSize(16);e.setTypeface(font(a));e.setTextColor(INK);e.setInputType(input);e.setTypeface(font(a));e.setText(value);e.setBackground(bg(a,Color.rgb(242,245,242)));e.setPadding(dp(a,12),dp(a,8),dp(a,12),dp(a,8));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(a,48));lp.setMargins(0,0,0,dp(a,10));p.addView(e,lp);return e;}
 static LinearLayout pair(Activity a,LinearLayout p){LinearLayout row=new LinearLayout(a);p.addView(row);return row;}
 static ScrollView scroll(View view){if(view instanceof ScrollView&&view.getVisibility()==View.VISIBLE)return (ScrollView)view;if(view instanceof ViewGroup)for(int n=0;n<((ViewGroup)view).getChildCount();n++){ScrollView found=scroll(((ViewGroup)view).getChildAt(n));if(found!=null)return found;}return null;}
 // Rebuilding content after an edit must not send the reader back to its first button.
 static void keepScroll(Activity a,Runnable redraw){ScrollView old=scroll(a.getWindow().getDecorView());int x=old==null?0:old.getScrollX(),y=old==null?0:old.getScrollY();redraw.run();if(old==null)return;ScrollView current=scroll(a.getWindow().getDecorView());if(current==null)return;current.setDescendantFocusability(ViewGroup.FOCUS_BEFORE_DESCENDANTS);current.setFocusableInTouchMode(true);current.requestFocus();current.getViewTreeObserver().addOnGlobalLayoutListener(new android.view.ViewTreeObserver.OnGlobalLayoutListener(){public void onGlobalLayout(){current.getViewTreeObserver().removeOnGlobalLayoutListener(this);restoreScroll(current,x,y);}});current.post(()->restoreScroll(current,x,y));}
 static void restoreScroll(ScrollView scroll,int x,int y){int max=scroll.getChildCount()==0?0:Math.max(0,scroll.getChildAt(0).getHeight()-scroll.getHeight()+scroll.getPaddingTop()+scroll.getPaddingBottom());scroll.scrollTo(x,Math.max(0,Math.min(y,max)));}
 static LinearLayout page(LinearLayout content){return (LinearLayout)content.getParent().getParent();}
 static void topAction(Activity a,LinearLayout content,String label,Runnable action){LinearLayout bar=(LinearLayout)page(content).getChildAt(0);Button b=link(a,bar,label,action);b.setTextSize(14);b.setLayoutParams(new LinearLayout.LayoutParams(dp(a,64),dp(a,40)));}
 static void tabs(Activity a,LinearLayout content,boolean agenda){tabs(a,content,agenda?1:0);}
 static void tabs(Activity a,LinearLayout content,int current){
  LinearLayout bar=new LinearLayout(a);bar.setPadding(dp(a,16),dp(a,5),dp(a,16),dp(a,3));bar.setBackgroundColor(0xFFFAFBFC);page(content).addView(bar,new LinearLayout.LayoutParams(-1,dp(a,64)));
  String[] names={"作业","课表","我的"};Class<?>[] targets={MainActivity.class,AgendaActivity.class,ProfileActivity.class};
  for(int k=0;k<3;k++){final int index=k;boolean selected=k==current;LinearLayout item=column(a);item.setGravity(Gravity.CENTER);bar.addView(item,new LinearLayout.LayoutParams(0,-1,1));item.setContentDescription("切换到"+names[k]);item.setSelected(selected);item.setFocusable(true);item.setClickable(true);item.setOnClickListener(v->{if(index==current)return;a.startActivity(new android.content.Intent(a,targets[index]).addFlags(android.content.Intent.FLAG_ACTIVITY_CLEAR_TOP|android.content.Intent.FLAG_ACTIVITY_SINGLE_TOP));if(!(a instanceof MainActivity))a.finish();});NavIcon icon=new NavIcon(a,k,selected);if(selected)icon.setBackground(bg(a,0xFFDDEDE7));item.addView(icon,new LinearLayout.LayoutParams(dp(a,50),dp(a,28)));TextView label=text(a,names[k],12);label.setGravity(Gravity.CENTER);label.setPadding(0,dp(a,2),0,0);label.setTextColor(selected?GREEN:MUTED);label.setTypeface(selected?strong(a):font(a));item.addView(label);}
 }
 static final class NavIcon extends View {
  final int type;final boolean selected;final Paint paint=new Paint(3);
  NavIcon(Activity a,boolean calendar,boolean selected){this(a,calendar?1:0,selected);}
  NavIcon(Activity a,int type,boolean selected){super(a);this.type=type;this.selected=selected;setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);}
  protected void onDraw(Canvas canvas){super.onDraw(canvas);float unit=getResources().getDisplayMetrics().density;canvas.save();canvas.translate(getWidth()/2f-10*unit,getHeight()/2f-9*unit);canvas.scale(unit,unit);paint.setColor(selected?GREEN:MUTED);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(1.7f);paint.setStrokeCap(Paint.Cap.ROUND);
   if(type==2){canvas.drawCircle(10,4,3.8f,paint);canvas.drawArc(2,9,18,23,180,180,false,paint);canvas.drawLine(2,16,18,16,paint);}
   else if(type==1){canvas.drawRoundRect(1,2,19,18,3,3,paint);canvas.drawLine(1,7,19,7,paint);canvas.drawLine(6,0,6,4,paint);canvas.drawLine(14,0,14,4,paint);for(int y=10;y<=14;y+=4)for(int x=5;x<=15;x+=5)canvas.drawPoint(x,y,paint);}
   else{canvas.drawRoundRect(3,0,17,18,2,2,paint);canvas.drawLine(7,5,13,5,paint);canvas.drawLine(7,9,13,9,paint);canvas.drawLine(7,13,11,13,paint);}canvas.restore();}
 }
 static void segments(Activity a,LinearLayout parent,String[] labels,int selected,java.util.function.IntConsumer action){LinearLayout row=new LinearLayout(a);row.setPadding(dp(a,4),dp(a,4),dp(a,4),dp(a,4));row.setBackground(bg(a,0xFFE8EEEB));parent.addView(row,new LinearLayout.LayoutParams(-1,dp(a,48)));for(int k=0;k<labels.length;k++){final int index=k;Button b=link(a,row,labels[k],()->action.accept(index));b.setSelected(k==selected);b.setTextColor(k==selected?GREEN:MUTED);if(k==selected)b.setBackground(bg(a,Color.WHITE));b.setLayoutParams(new LinearLayout.LayoutParams(0,-1,1));b.setContentDescription(labels[k]+(k==selected?"，当前页面":"，点击切换"));}}
 static LinearLayout half(Activity a,LinearLayout row,boolean right){LinearLayout box=column(a);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(right?dp(a,6):0,0,right?0:dp(a,6),0);row.addView(box,lp);return box;}
 static void error(Activity a,Exception e){new AlertDialog.Builder(a).setTitle("请核对").setMessage(e.getMessage()==null?"内容格式有误":e.getMessage()).setPositiveButton("知道了",null).show();}
}
